// Finite native harmonic descriptors and one-origin comparisons for YM2151 measurements.
package main
import("crypto/sha256";"encoding/csv";"encoding/json";"flag";"fmt";"math";"os";"strconv")
type harmonic struct{Order int `json:"order"`;Sin float64 `json:"sin_pcm"`;Cos float64 `json:"cos_pcm"`;Power float64 `json:"power_pcm_squared"`}
type projection struct{Samples int `json:"samples"`;First int `json:"first_sample"`;End int `json:"end_sample_exclusive"`;DC float64 `json:"dc_pcm"`;RMS float64 `json:"raw_rms_pcm"`;Residual float64 `json:"projection_rms_pcm"`;Holdout float64 `json:"own_training_prediction_holdout_rms_pcm"`;PivotRatio float64 `json:"cholesky_pivot_ratio_diagnostic"`;Terms []harmonic `json:"harmonics"`;State string `json:"state"`}
type phase_match struct{Phase *float64 `json:"one_shared_phase_radians"`;State string `json:"alignment_state"`;EquivalentMinima int `json:"numerically_equivalent_phase_origins"`;CoefficientRMS float64 `json:"phase_aligned_coefficient_rms_pcm"`;HoldoutRMS float64 `json:"model_projection_holdout_rms_pcm"`;DCdifference float64 `json:"observed_dc_difference_pcm"`;Gain string `json:"gain_policy"`}
type spectral_job struct{column,model_column,reference,output string;increment float64;harmonics,start,end,train,hold_end int}
func main(){var job spectral_job;flag.StringVar(&job.column,"column","right","input PCM column");flag.StringVar(&job.model_column,"model-column","right","reference PCM column");flag.StringVar(&job.reference,"reference","","optional model CSV,one shared phase only");flag.StringVar(&job.output,"csv","","fresh unaligned prediction CSV");flag.Float64Var(&job.increment,"increment",4124,"independently qualified native20-bit increment");flag.IntVar(&job.harmonics,"harmonics",64,"fixed harmonic count1..64");flag.IntVar(&job.start,"start-sample",1024,"interior first sample");flag.IntVar(&job.end,"end-sample",0,"interior end,0=file end");flag.IntVar(&job.train,"train-start",8192,"training first sample");flag.IntVar(&job.hold_end,"holdout-end",5120,"earlier holdout end");flag.Parse();e:=job.run();if e!=nil{fmt.Fprintln(os.Stderr,e);os.Exit(1)}}
func(job *spectral_job)run()error{
 if flag.NArg()!=1{return fmt.Errorf("use [flags] INPUT.csv")};raw,e:=os.ReadFile(flag.Arg(0));if e!=nil{return e};v,e:=read_phase_csv(raw,job.column);if e!=nil{return e};if job.end==0{job.end=len(v)};for _,x:=range v{if x!=math.Trunc(x){return fmt.Errorf("PCM must be integral")}};w:=2*math.Pi*job.increment/(1<<20)
 if job.harmonics<1||job.harmonics>64||job.increment<=0||job.increment*float64(job.harmonics)>=1<<19||math.IsNaN(w)||math.IsInf(w,0){return fmt.Errorf("invalid frequency or aliased harmonic support")}
 if job.start<0||job.end>len(v)||job.start+1024>job.hold_end||job.hold_end>job.train||job.train+2048>job.end{return fmt.Errorf("invalid separate training/holdout bounds")}
 result,e:=project(v,job.train,job.end,job.harmonics,w);if e!=nil{return e};result.Holdout=prediction_rms(v,job.start,job.hold_end,result,w,0)
 out:=map[string]interface{}{"input":flag.Arg(0),"input_sha256":fmt.Sprintf("%x",sha256.Sum256(raw)),"column":job.column,"native_stride":1,"independently_qualified_increment_20bit":job.increment,"training_projection":result,"holdout_first":job.start,"holdout_end_exclusive":job.hold_end,"assumptions":[]string{"Finite fixed-frequency projection; no forced period or measured fundamental returned","Absolute PCM gain/DC retained; no per-harmonic,per-window,or cycle alignment","Projection residual and held-out error remain observations; high feedback may be aperiodic","Native output can contain intrinsic aliases; no internal spectrum claim"}}
 out["simple_tone_control"]=estimate_tone(v,job.start,job.end)
 var ref projection;var match phase_match
 if job.reference!=""{other,e:=os.ReadFile(job.reference);if e!=nil{return e};model,e:=read_phase_csv(other,job.model_column);if e!=nil{return e};if len(model)<job.end{return fmt.Errorf("reference input too short")};for _,x:=range model{if x!=math.Trunc(x){return fmt.Errorf("reference PCM must be integral")}};ref,e=project(model,job.train,job.end,job.harmonics,w);if e!=nil{return e};match=align(result,ref);if match.Phase!=nil{match.HoldoutRMS=prediction_rms(v,job.start,job.hold_end,ref,w,*match.Phase)};out["reference"]=job.reference;out["reference_sha256"]=fmt.Sprintf("%x",sha256.Sum256(other));out["reference_training_projection"]=ref;out["one_phase_comparison"]=match}
 if job.output!=""{e=job.write_curve(v,result,ref,match,w);if e!=nil{return e};b,e:=os.ReadFile(job.output);if e!=nil{return e};out["curve_csv"]=job.output;out["curve_sha256"]=fmt.Sprintf("%x",sha256.Sum256(b))}
 return json.NewEncoder(os.Stdout).Encode(out)
}
func project(v []float64,first,end,h int,w float64)(projection,error){
 r:=projection{Samples:end-first,First:first,End:end,Terms:[]harmonic{},State:"finite_projection_periodicity_unproven"};size:=2*h+1;if first<0||end>len(v)||end-first<4*size{return r,fmt.Errorf("insufficient projection samples")}
 c,s:=make([]float64,2*h+1),make([]float64,2*h+1);c[0]=float64(end-first)
 for k:=1;k<=2*h;k++{x:=float64(k)*w;scale:=math.Sin(float64(end-first)*x/2)/math.Sin(x/2);s[k],c[k]=math.Sincos(x*(float64(first)+float64(end-first-1)/2));s[k]*=scale;c[k]*=scale}
 C:=func(k int)float64{if k<0{k=-k};return c[k]};S:=func(k int)float64{if k<0{return -s[-k]};return s[k]}
 gram:=make([][]float64,size);rhs:=make([]float64,size);for i:=range gram{gram[i]=make([]float64,size)};gram[0][0]=c[0]
 for j:=1;j<=h;j++{a,b:=2*j-1,2*j;gram[0][a]=s[j];gram[a][0]=s[j];gram[0][b]=c[j];gram[b][0]=c[j];for k:=1;k<=h;k++{d,e:=2*k-1,2*k;gram[a][d]=.5*(C(j-k)-C(j+k));gram[b][e]=.5*(C(j-k)+C(j+k));gram[a][e]=.5*(S(j+k)+S(j-k));gram[b][d]=.5*(S(j+k)-S(j-k))}}
 sumsq,nonzero:=0.,false;for n:=first;n<end;n++{x:=v[n];if math.IsNaN(x)||math.IsInf(x,0){return r,fmt.Errorf("nonfinite sample")};rhs[0]+=x;sumsq+=x*x;if x!=0{nonzero=true};for k:=1;k<=h;k++{sn,cs:=math.Sincos(float64(k)*w*float64(n));rhs[2*k-1]+=x*sn;rhs[2*k]+=x*cs}}
 beta,ratio,e:=solve_positive(gram,rhs);if e!=nil{return r,e};r.PivotRatio=ratio;r.DC=beta[0];r.RMS=math.Sqrt(sumsq/float64(end-first));for k:=1;k<=h;k++{a,b:=beta[2*k-1],beta[2*k];r.Terms=append(r.Terms,harmonic{k,a,b,.5*(a*a+b*b)})};r.Residual=prediction_rms(v,first,end,r,w,0);if !nonzero{r.State="quiet_exact_zero"};return r,nil
}
func solve_positive(a [][]float64,b []float64)([]float64,float64,error){
 n:=len(b);l:=make([][]float64,n);minimum,maximum:=math.Inf(1),0.;for i:=range l{l[i]=make([]float64,n);for j:=0;j<=i;j++{x:=a[i][j];for k:=0;k<j;k++{x-=l[i][k]*l[j][k]};if i==j{if x<=a[0][0]*1e-12{return nil,0,fmt.Errorf("ill-conditioned harmonic basis")};minimum=math.Min(minimum,x);maximum=math.Max(maximum,x);l[i][j]=math.Sqrt(x)}else{l[i][j]=x/l[j][j]}}}
 x:=make([]float64,n);for i:=0;i<n;i++{v:=b[i];for j:=0;j<i;j++{v-=l[i][j]*x[j]};x[i]=v/l[i][i]};for i:=n-1;i>=0;i--{v:=x[i];for j:=i+1;j<n;j++{v-=l[j][i]*x[j]};x[i]=v/l[i][i]};return x,maximum/minimum,nil
}
func prediction_rms(v []float64,first,end int,p projection,w,phase float64)float64{sum:=0.;for n:=first;n<end;n++{d:=v[n]-predict(p,w*float64(n)+phase);sum+=d*d};return math.Sqrt(sum/float64(end-first))}
func predict(p projection,theta float64)float64{value:=p.DC;for _,x:=range p.Terms{s,c:=math.Sincos(float64(x.Order)*theta);value+=x.Sin*s+x.Cos*c};return value}
func align(observed,reference projection)phase_match{
 cost:=func(phase float64)float64{d:=observed.DC-reference.DC;sum:=d*d;for i,a:=range observed.Terms{b:=reference.Terms[i];s,c:=math.Sincos(float64(a.Order)*phase);ds:=a.Sin-(b.Sin*c-b.Cos*s);dc:=a.Cos-(b.Cos*c+b.Sin*s);sum+=.5*(ds*ds+dc*dc)};return sum}
 energy:=0.;for _,h:=range observed.Terms{energy+=h.Power};for _,h:=range reference.Terms{energy+=h.Power};if energy<1e-12{return phase_match{State:"phase_unobservable_no_harmonic_support",CoefficientRMS:math.Abs(observed.DC-reference.DC),DCdifference:observed.DC-reference.DC,Gain:"fixed absolute PCM; no fitted gain or DC correction"}}
 const grid=2048;step:=2*math.Pi/grid;values:=make([]float64,grid);for i:=range values{values[i]=cost(float64(i)*step)};type minimum struct{phase,cost float64};minima:=[]minimum{};best:=minimum{0,math.Inf(1)}
 for i,x:=range values{if x>values[(i+grid-1)%grid]||x>values[(i+1)%grid]{continue};lo,hi:=(float64(i)-1)*step,(float64(i)+1)*step;for j:=0;j<48;j++{a,b:=lo+(hi-lo)*.3819660112501051,lo+(hi-lo)*.6180339887498949;if cost(a)<cost(b){hi=b}else{lo=a}};phase:=(lo+hi)/2;phase=math.Mod(phase+2*math.Pi,2*math.Pi);m:=minimum{phase,cost(phase)};minima=append(minima,m);if m.cost<best.cost{best=m}}
 scale:=1.;for _,h:=range observed.Terms{scale+=h.Power};count:=0;for _,m:=range minima{if m.cost<=best.cost+1e-10*scale{count++}};return phase_match{Phase:&best.phase,State:"single_origin_fitted_on_training_only",EquivalentMinima:count,CoefficientRMS:math.Sqrt(best.cost),DCdifference:observed.DC-reference.DC,Gain:"fixed absolute PCM; no fitted gain or DC correction"}
}
func(job *spectral_job)write_curve(v []float64,p,ref projection,match phase_match,w float64)error{
 f,e:=os.OpenFile(job.output,os.O_WRONLY|os.O_CREATE|os.O_EXCL,0600);if e!=nil{return e};writer:=csv.NewWriter(f);e=writer.Write([]string{"sample","input_pcm","prediction_from_training_pcm","reference_one_phase_prediction_pcm","own_residual_pcm"});if e!=nil{f.Close();return e};for n:=job.start;n<job.end;n++{own:=predict(p,w*float64(n));other:="";if job.reference!=""&&match.Phase!=nil{other=strconv.FormatFloat(predict(ref,w*float64(n)+*match.Phase),'g',17,64)};e=writer.Write([]string{strconv.Itoa(n),strconv.FormatFloat(v[n],'g',17,64),strconv.FormatFloat(own,'g',17,64),other,strconv.FormatFloat(v[n]-own,'g',17,64)});if e!=nil{f.Close();return e}};writer.Flush();e=writer.Error();close_error:=f.Close();if e!=nil{return e};return close_error
}

type tone_observation struct{State string `json:"state"`;Crossings int `json:"positive_midpoint_crossings"`;Increment *float64 `json:"measured_native_increment_20bit"`;Period *float64 `json:"measured_native_samples_per_cycle"`;Amplitude float64 `json:"fitted_peak_pcm"`;Residual float64 `json:"fitted_sine_rms_pcm"`;Relative float64 `json:"relative_sine_rms"`;Offset float64 `json:"fitted_dc_pcm"`}
func estimate_tone(v []float64,first,end int)tone_observation{
 r:=tone_observation{State:"unresolved_not_a_qualified_simple_sine"};lo,hi:=v[first],v[first];for _,x:=range v[first:end]{lo=math.Min(lo,x);hi=math.Max(hi,x)};if hi-lo<32{return r};mid:=(hi+lo)/2;crossings:=[]float64{};for n:=first+1;n<end;n++{if v[n-1]<=mid&&v[n]>mid{crossings=append(crossings,float64(n-1)+(mid-v[n-1])/(v[n]-v[n-1]))}};r.Crossings=len(crossings);if len(crossings)<8{return r};mx,my:=float64(len(crossings)-1)/2,0.;for _,x:=range crossings{my+=x};my/=float64(len(crossings));num,den:=0.,0.;for i,x:=range crossings{d:=float64(i)-mx;num+=d*(x-my);den+=d*d};period:=num/den;if period<=2{return r};w:=2*math.Pi/period;p,e:=project(v,first,end,1,w);if e!=nil{return r};r.Amplitude=math.Hypot(p.Terms[0].Sin,p.Terms[0].Cos);r.Residual=p.Residual;r.Offset=p.DC;r.Relative=p.Residual/r.Amplitude;if p.Residual>math.Max(1,.02*r.Amplitude){return r};inc:=(1<<20)/period;r.State="finite_simple_sine_control_measured";r.Increment=&inc;r.Period=&period;return r
}
